// CONSTANTS
// =================================================================================================

const COMPONENT: &str = "miden-funding-service";

/// Tracing target used for user-visible events.
pub const LOG_TARGET: &str = "user::miden-funding-service";

/// Default largest amount one request may ask for, in base units of the native asset.
pub const DEFAULT_MAX_AMOUNT: u64 = 1_000_000_000;

/// Default largest number of notes one funding transaction creates.
pub const DEFAULT_MAX_NOTES_PER_TX: NonZeroUsize =
    NonZeroUsize::new(16).expect("literal is non-zero");

const _: () = assert!(DEFAULT_MAX_NOTES_PER_TX.get() <= MAX_NOTES_PER_TX.get());

/// Hard bound on `--max-notes-per-tx`.
pub const MAX_NOTES_PER_TX: NonZeroUsize = NonZeroUsize::new(100).expect("literal is non-zero");

/// Default number of blocks after its reference block at which a funding transaction expires.
pub const DEFAULT_TX_EXPIRATION_DELTA: NonZeroU16 =
    NonZeroU16::new(50).expect("literal is non-zero");

/// Default interval for syncing the wallet and checking submitted transactions.
pub const DEFAULT_POLL_INTERVAL: Duration = Duration::from_secs(1);

/// Default timeout of a request to the node's RPC API.
pub const DEFAULT_RPC_TIMEOUT: Duration = Duration::from_secs(10);

/// Default timeout of a request to the remote prover.
pub const DEFAULT_TX_PROVER_TIMEOUT: Duration = Duration::from_secs(60);

/// Default timeout of an HTTP request served by this service.
pub const DEFAULT_HTTP_TIMEOUT: Duration = Duration::from_secs(30);

// CONFIGURATION
// =================================================================================================

/// The configuration of the funding service.
pub struct FundingServiceConfig {
    max_decoding_message_size: usize,
    rpc_url: Url,
    signing_key_file: PathBuf,
    data_directory: PathBuf,
    validator_signing_public_keys: Vec<ValidatorPublicKey>,
    tx_prover_url: Option<Url>,
    http_timeout: Duration,
    rpc_timeout: Duration,
    tx_prover_timeout: Duration,
    max_amount: u64,
    max_notes_per_tx: NonZeroUsize,
    tx_expiration_delta: NonZeroU16,
    poll_interval: Duration,
}

impl FundingServiceConfig {
    /// Sets the maximum encoded size accepted by each outgoing gRPC client.
    #[must_use]
    pub fn with_max_decoding_message_size(mut self, limit: usize) -> Self {
        self.max_decoding_message_size = limit;
        self
    }

    /// Creates a configuration with default timeouts and limits.
    pub fn new(
        rpc_url: Url,
        signing_key_file: PathBuf,
        validator_signing_public_keys: Vec<ValidatorPublicKey>,
        data_directory: PathBuf,
    ) -> Self {
        Self {
            rpc_url,
            max_decoding_message_size: miden_node_utils::grpc::DEFAULT_MAX_DECODING_MESSAGE_SIZE,
            signing_key_file,
            data_directory,
            validator_signing_public_keys,
            tx_prover_url: None,
            http_timeout: DEFAULT_HTTP_TIMEOUT,
            rpc_timeout: DEFAULT_RPC_TIMEOUT,
            tx_prover_timeout: DEFAULT_TX_PROVER_TIMEOUT,
            max_amount: DEFAULT_MAX_AMOUNT,
            max_notes_per_tx: DEFAULT_MAX_NOTES_PER_TX,
            tx_expiration_delta: DEFAULT_TX_EXPIRATION_DELTA,
            poll_interval: DEFAULT_POLL_INTERVAL,
        }
    }

    /// Sets the remote prover to use. Without one the service proves locally.
    #[must_use]
    pub fn with_tx_prover_url(mut self, url: Option<Url>) -> Self {
        self.tx_prover_url = url;
        self
    }

    #[must_use]
    pub fn with_http_timeout(mut self, timeout: Duration) -> Self {
        self.http_timeout = timeout;
        self
    }

    #[must_use]
    pub fn with_rpc_timeout(mut self, timeout: Duration) -> Self {
        self.rpc_timeout = timeout;
        self
    }

    #[must_use]
    pub fn with_tx_prover_timeout(mut self, timeout: Duration) -> Self {
        self.tx_prover_timeout = timeout;
        self
    }

    #[must_use]
    pub fn with_max_amount(mut self, max_amount: u64) -> Self {
        self.max_amount = max_amount;
        self
    }

    #[must_use]
    pub fn with_max_notes_per_tx(mut self, max_notes_per_tx: NonZeroUsize) -> Self {
        self.max_notes_per_tx = max_notes_per_tx;
        self
    }

    #[must_use]
    pub fn with_tx_expiration_delta(mut self, delta: NonZeroU16) -> Self {
        self.tx_expiration_delta = delta;
        self
    }

    #[must_use]
    pub fn with_poll_interval(mut self, interval: Duration) -> Self {
        self.poll_interval = interval;
        self
    }

    /// Connects to the node and builds the service.
    #[miden_instrument(
        target = COMPONENT,
        name = "funding.initialize",
        fields(
            funding_service.remote_prover = self.tx_prover_url.is_some(),
        ),
        err,
    )]
    pub async fn build(self) -> anyhow::Result<FundingService> {
        anyhow::ensure!(
            self.max_notes_per_tx <= MAX_NOTES_PER_TX,
            "--max-notes-per-tx must not exceed {MAX_NOTES_PER_TX} because the node limits how \
             many note IDs one lookup may hold",
        );

        anyhow::ensure!(!self.poll_interval.is_zero(), "--poll-interval must be greater than zero");

        let database_filepath = self.data_directory.join(lifecycle::DATABASE_FILENAME);
        anyhow::ensure!(
            database_filepath.is_file(),
            "funding database {} not found; run bootstrap before start",
            database_filepath.display(),
        );

        let node = RpcNodeClient::connect(
            &self.rpc_url,
            self.rpc_timeout,
            self.validator_signing_public_keys,
            self.max_decoding_message_size,
        )
        .await
        .context("failed to connect to the node RPC API")?;

        // The fee asset is constant for the chain and is only named by the protocol configuration,
        // which the node serves with the genesis block header. The remaining fee parameters are in
        // every block header, and the worker publishes them with its synchronized balance.
        let protocol_config = node.protocol_config().clone();
        let fee_asset_id = protocol_config.fee_asset_id();
        let database = db::FundingDatabase::open_and_verify(
            &database_filepath,
            node.genesis_commitment(),
            fee_asset_id,
        )
        .await
        .context("failed to open the funding database; check its network and migration status")?;
        let secret_key = fs_err::read(&self.signing_key_file)
            .map_err(anyhow::Error::from)
            .and_then(|bytes| {
                AuthSecretKey::read_from_bytes(&bytes)
                    .context("failed to decode the funding signing key")
            })?;
        let (initial_header, _) = node
            .tip_chain_state()
            .await
            .context("failed to read the chain state from the node")?;
        let chain_tip = initial_header.block_num();
        let wallet = FundingWallet::load_at(
            &mut node.rpc_client(),
            database.identity().funding_account_id,
            secret_key,
            fee_asset_id,
            chain_tip,
        )
        .await
        .context("failed to load the public funding account from the node")?;
        miden_span_record!(account.id = wallet.account_id());
        // The native faucet cannot change the symbol, the decimals or the name of its asset, so the
        // service reads them once.
        let native_faucet =
            UsdcxFaucet::load_at(&mut node.rpc_client(), fee_asset_id.faucet_id(), chain_tip)
                .await
                .context("failed to read the native faucet account")?;
        let metadata = native_faucet
            .metadata()
            .context("the native faucet account is not a fungible faucet")?;
        let native_asset = NativeAsset::new(fee_asset_id, &metadata);

        // A note holds the amount as a fungible asset, so an amount the asset type cannot express
        // must fail at startup instead of on every request.
        FungibleAsset::new(fee_asset_id.faucet_id(), self.max_amount)
            .context("--max-amount is not a valid amount of the native asset")?;

        let prover = match self.tx_prover_url {
            Some(url) => {
                Prover::remote(url, self.tx_prover_timeout, self.max_decoding_message_size)
                    .context("failed to build the remote prover client")?
            },
            None => Prover::local(),
        };

        info!(
            target: LOG_TARGET,
            "Funding service initialized",
            account.id = wallet.account_id(),
            asset.faucet_id = fee_asset_id.faucet_id(),
            genesis.commitment = node.genesis_commitment(),
            funding_service.max_amount = self.max_amount,
            funding_service.max_notes_per_tx = self.max_notes_per_tx.get(),
            funding_service.tx_expiration_delta = self.tx_expiration_delta.get(),
            funding_service.remote_prover = matches!(prover, Prover::Remote(_))
        );

        Ok(FundingService {
            database,
            node,
            prover,
            wallet,
            initial_header,
            fee_asset_id,
            native_asset,
            fee_faucet: native_faucet,
            protocol_config,
            worker_config: WorkerConfig {
                max_notes_per_tx: self.max_notes_per_tx,
                expiration_delta: self.tx_expiration_delta,
                poll_interval: self.poll_interval,
            },
            max_amount: self.max_amount,
            http_timeout: self.http_timeout,
        })
    }
}

// FUNDING SERVICE
// =================================================================================================

/// The funding service, ready to run.
pub struct FundingService {
    database: db::FundingDatabase,
    node: RpcNodeClient,
    prover: Prover,
    wallet: FundingWallet,
    initial_header: BlockHeader,
    fee_asset_id: AssetId,
    native_asset: NativeAsset,
    fee_faucet: UsdcxFaucet,
    protocol_config: ProtocolConfig,
    worker_config: WorkerConfig,
    max_amount: u64,
    http_timeout: Duration,
}

impl FundingService {
    /// Runs the HTTP server and funding worker until one of them stops.
    pub async fn run(
        self,
        listener: TcpListener,
        shutdown: CancellationToken,
    ) -> anyhow::Result<()> {
        let status =
            StatusSnapshot::new(self.wallet.account_id(), self.native_asset, self.max_amount);
        status.update(
            self.wallet
                .account()
                .vault()
                .get_balance(self.fee_asset_id)
                .map_or(0, |amount| amount.as_u64()),
            self.initial_header.block_num(),
            self.initial_header.fee_parameters().verification_base_fee(),
        );
        let database = Arc::new(self.database);

        let mut tasks = Tasks::new();

        let server = FundingServer::new(
            Arc::clone(&database),
            status.clone(),
            self.fee_asset_id,
            self.http_timeout,
        );
        let server_shutdown = shutdown.clone();
        tasks.spawn("http-server", async move {
            server
                .serve(listener, server_shutdown)
                .await
                .context("the funding service HTTP server failed")
        });

        let funder = Funder::new(
            self.node,
            self.prover,
            FunderSetup {
                database,
                wallet: self.wallet,
                fee_asset_id: self.fee_asset_id,
                fee_faucet: self.fee_faucet,
                protocol_config: self.protocol_config,
                config: self.worker_config,
                status,
            },
        );
        let worker_shutdown = shutdown.clone();
        tasks.spawn("funder", async move {
            Box::pin(funder.run(worker_shutdown)).await.context("the funding worker failed")
        });

        tasks
            .join_next_or_cancelled(shutdown)
            .await
            .context("a funding service task failed")
    }
}
